cat > /app/output/check.py <<'PY'
import numpy as np,json
from PIL import Image
for name in ['initial','grasp_height','turn1']:
 p='/app/runs/'+name;m=json.load(open(p+'/meta.json'));print('\n',name,'tcp',m['proprio']['now'][:3])
 for cam in ['front','left','right','topview']:
  im=np.array(Image.open(p+'/'+cam+'.png'));D=np.load(p+'/depth_'+cam+'.npy').squeeze().astype(float);K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);
  mask=(im[:,:,1]>130)&(im[:,:,0]<100)&(im[:,:,2]>130)
  v,u=np.where(mask);d=D[v,u];P=np.c_[(u-160)*d/K[0,0],-(v-120)*d/K[1,1],-d,np.ones(len(d))]@T.T
  if len(P): print(cam,'uv',np.median(u),np.median(v),'pts',np.median(P[:,:3],0), 'range',P[:,:3].min(0),P[:,:3].max(0))
PY
python /app/output/check.py

